    // The last hop pushes straight to the next global round.","      frontierPushToLocal = hop + 1u < FRONTIER_LOCAL_ITERATIONS;","      frontierLocalWriteHalf = (hop + 1u) & 1u;","      if (localInvocationIndex < localLength) {","        visit(frontierLocalQueue[readHalf * 256u + localInvocationIndex]);","    workgroupBarrier();","const costsOffset: u32 = 0u;","@group(0) @binding(0) var<storage, read> costs: array<f32>;","const hopsInOffset: u32 = 0u;","@group(0) @binding(1) var<storage, read> hopsIn: array<u32>;","const hopDistancesOffset: u32 = 0u;","@group(0) @binding(2) var<storage, read_write> hopDistances: array<u32>;","const MAXIMUM_HOPS: u32 = 8u;","  _ = &costs;","  _ = &hopsIn;","  _ = &hopDistances;","  let limit = min(hopsIn[hopsInOffset], MAXIMUM_HOPS);","  let cost = costs[costsOffset + index];","  // NaN and +Infinity compare false and stay outside the ego network.","  let inside = cost <= f32(limit);","  hopDistances[hopDistancesOffset + index] = select(NONE, u32(select(0.0, cost, inside)), inside);"],"strings":["read_write","network-neighborhood-costs","network-neighborhood-reachability-control","network-neighborhood-reachability-dispatch-even","network-neighborhood-reachability-queued-round","network-neighborhood-unit-weights","atomic<u32>","network-neighborhood-reachability-queues","network-neighborhood-reachability-dispatch-odd","read","GPUNetworkReachability","network-neighborhood-reachability-relax-7","network-neighborhood-reachability-relax-0","gpu-network.network-neighborhood-neighbors","gpu-network.network-neighborhood-offsets","network-neighborhood-reachability-relax-1","network-neighborhood-reachability-relax-2","network-neighborhood-reachability-relax-3","network-neighborhood-reachability-relax-4","network-neighborhood-reachability-relax-5","indirect","network-neighborhood-reachability-relax-6","network-neighborhood-reachability-seed","buffer","network-neighborhood-reachability-initialize","compute","network-neighborhood","node","contro